macro_rules! my_vec {
    () => { Vec::new() };
    ($($x:expr),+ $(,)?) => {{        // one-or-more exprs, optional trailing comma
        let mut v = Vec::new();
        $( v.push($x); )+             // repeat the push for each matched $x
        v
    }};
}
let v = my_vec![1, 2, 3];            // expands to the push sequence
